\documentclass{standalone}
\usepackage{pgfplots}
\usepackage{hyperref}
\usepackage{graphicx}
\usepackage{amsmath}
\usepackage{cancel}
%% For tabular environment
\usepackage[T1]{fontenc}
\usepackage{makecell}
\usetikzlibrary{calc, shapes.geometric} 
\usepackage{tkz-euclide}
\usetkzobj{all}

\begin{document}
\pagestyle{empty}

  \definecolor{deepskyblue}{rgb}{0.173,0.447,0.682}
    \definecolor{orangepeel}{rgb}{0.902, 0.624, 0}
    \definecolor{lightyellow}{rgb}{0.953,0.882,0.388}
    \definecolor{darkgreen}{rgb}{0.271, 0.608, 0.463}
    \definecolor{lightblue}{rgb}{0.484,0.702,0.894}
    \definecolor{rustred}{rgb}{0.784,0.392,0.149}
    \definecolor{fadedpink}{rgb}{0.753,0.494,0.643}

\begin{tikzpicture}[scale=1.1]

\tkzDefPoints{0/0/O}
\tkzDefShiftPoint[O](0:3.5){P}
\tkzDefShiftPoint[P](104:3){N}
\tkzDefShiftPoint[O](93:1.5){M}



\tkzMarkAngle[draw=none,size=.5, fill=darkgreen](M,N,P) 
\tkzMarkAngle[draw=none,size=.5, fill=lightblue](N,P,O) 
\tkzMarkAngle[draw=none,size=.5, fill=fadedpink](P,O,M) 
\tkzMarkAngle[draw=none,size=.5, fill=lightyellow](O,M,N) 

\tkzLabelAngle[pos=0.8,xshift=-5pt](M,N,P){$11x-2^{\circ}$}
\tkzLabelAngle[pos=0.8](N,P,O){ $76^{\circ}$}
\tkzLabelAngle[pos=0.8](P,O,M){$93^{\circ}$}
\tkzLabelAngle[pos=0.8,xshift=12pt](O,M,N){$14x-7^{\circ}$}

 \tkzDrawPolygon[style=very thick](M,O,P,N)
    \tkzLabelPoints[above,xshift=5pt](N)
    \tkzLabelPoints[left,yshift=5pt](M)
    \tkzLabelPoints[below,xshift=-5pt](O)
    \tkzLabelPoints[right,yshift=-5pt](P)

\end{tikzpicture}
\end{document}
